{:ok, counter} = Agent.start_link(fn -> 0 end)

1..8
|> Enum.map(fn _ ->
  Task.async(fn ->
    for _ <- 1..1000, do: Agent.update(counter, &(&1 + 1))
  end)
end)
|> Task.await_many()

IO.puts(Agent.get(counter, & &1)) # 8000

